#[inline]
pub fn get_regular_cell_class(case_code: u8) -> u8 {
    REGULAR_CELL_CLASS[case_code as usize]
}

#[inline]
pub fn get_regular_cell_data(class_index: u8) -> RegularCellData {
    REGULAR_CELL_DATA[class_index as usize]
}

#[inline]
pub fn get_regular_vertex_data(case_code: u8, vertex_index: u8) -> u16 {
    REGULAR_VERTEX_DATA[case_code as usize][vertex_index as usize]
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn table_sizes() {
        assert_eq!(REGULAR_CELL_CLASS.len(), 256);
        assert_eq!(REGULAR_CELL_DATA.len(), 16);
        assert_eq!(REGULAR_VERTEX_DATA.len(), 256);
        assert_eq!(REGULAR_VERTEX_DATA[0].len(), 12);
    }

    #[test]
    fn known_case_values() {
        assert_eq!(get_regular_cell_class(0), 0x00);
        assert_eq!(get_regular_cell_class(255), 0x00);
        assert_eq!(get_regular_cell_class(1), 0x01);
        let cd = get_regular_cell_data(1);
        assert_eq!(cd.triangle_count(), 1);
        assert_eq!(cd.vertex_count(), 3);
    }

    #[test]
    fn empty_rows_are_zero() {
        assert!(REGULAR_VERTEX_DATA[0].iter().all(|&v| v == 0));
        assert!(REGULAR_VERTEX_DATA[255].iter().all(|&v| v == 0));
    }
}
